import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-sociology-culture-socialization-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`Define socialization and its two phases.`]: {
    question: r`A 28-year-old accountant joins a new firm and over several months picks up its unwritten rules about email tone, meeting etiquette and when it is acceptable to leave for the day. This learning is best classified as:`,
    options: [r`primary socialization, because the rules are basic ones`, r`secondary socialization, because it comes after childhood`, r`primary socialization, because it happens face to face`, r`secondary socialization, because the family teaches it`],
    correctAnswer: 1,
    explanation: r`Secondary socialization is the learning of norms that continues through life in settings such as school and work, which is what the accountant is doing. Primary socialization is the childhood phase centred on the family, so calling this primary confuses the phase with how basic or how personal the rules are. The family is the agent of the primary phase, not of this one.`,
  },
  [r`Contrast norms, mores, and folkways.`]: {
    question: r`In one town, residents who skip the customary handshake greeting get puzzled looks. Residents caught cheating elderly neighbors out of their savings are condemned as dishonest and reported to the police. The handshake rule and the anti-fraud rule are, respectively:`,
    options: [r`a more and a folkway`, r`a folkway and a taboo`, r`a taboo and a folkway`, r`a folkway and a more`],
    correctAnswer: 3,
    explanation: r`The handshake is an everyday custom whose violation draws only mild disapproval, which makes it a folkway. The rule against fraud carries strong moral weight and serious sanctions, which makes it a more. A taboo would provoke revulsion, not just condemnation, and the reversed pairing swaps the strength of the two reactions.`,
  },
  [r`What is the difference between assimilation and multiculturalism?`]: {
    question: r`School A teaches only in the majority language and discourages students from wearing heritage dress. School B funds heritage-language classes and marks every group's holidays on the school calendar. Which approach does each school follow?`,
    options: [r`multiculturalism at A, assimilation at B`, r`amalgamation at A, multiculturalism at B`, r`assimilation at A, multiculturalism at B`, r`assimilation at A, amalgamation at B`],
    correctAnswer: 2,
    explanation: r`School A pushes minority students to be absorbed into the dominant culture, which is assimilation, while School B preserves distinct identities side by side, which is multiculturalism. Reversing the two swaps the definitions. Amalgamation would mean the groups blending into a new shared culture, and neither school does that.`,
  },
  [r`What are agents of socialization?`]: {
    question: r`A researcher studying how a teenager came to value punctuality lists four influences on her. Which one would NOT count as an agent of socialization?`,
    options: [r`a parent who praises being early`, r`a gene variant linked to early waking`, r`a teacher who marks late work down`, r`a team that benches latecomers`],
    correctAnswer: 1,
    explanation: r`Agents of socialization are the social sources that transmit culture: family, schools, peer groups, media and workplaces. A gene variant is a biological influence, not a source that teaches norms. The parent, the teacher and the team are family, school and peer-group agents, each rewarding or punishing the behavior.`,
  },
  [r`Distinguish material and non-material culture.`]: {
    question: r`An archaeologist records four things about an ancient settlement: clay cooking pots, a rule against lending at interest, bronze coins, and a belief in a river spirit. Which pair belongs entirely to non-material culture?`,
    options: [r`the lending rule and the river-spirit belief`, r`the cooking pots and the bronze coins`, r`the bronze coins and the lending rule`, r`the cooking pots and the river-spirit belief`],
    correctAnswer: 0,
    explanation: r`Non-material culture is made of beliefs, values, language and norms, so the rule and the belief both qualify. Pots and coins are physical objects, which makes them material culture. The mixed pairs each include one object, a common slip when an object is closely tied to an idea such as money or cooking customs.`,
  },
  [r`What is cultural relativism vs. ethnocentrism?`]: {
    question: r`Two travelers watch a community eat its main meal seated on the floor from one shared platter. The first writes, "This is backward compared with the proper way we eat at home." The second writes, "Here the shared platter expresses kinship, and it fits their values about hospitality." The two notes show, in order:`,
    options: [r`ethnocentrism, then cultural relativism`, r`cultural relativism, then ethnocentrism`, r`xenocentrism, then cultural relativism`, r`ethnocentrism, then xenocentrism`],
    correctAnswer: 0,
    explanation: r`The first traveler judges the practice by the standards of his own culture, which is ethnocentrism. The second judges it by the community's own standards, which is cultural relativism. Xenocentrism would mean rating the foreign practice as better than one's own, and neither note does that.`,
  },
  [r`Define cultural capital.`]: {
    question: r`Two fellowship applicants have equal grades and equal family income. One grew up visiting museums, knows how to address a selection panel and handles a formal dinner with ease, and the panel rates her as "polished" and picks her. Her advantage is best described as:`,
    options: [r`cultural capital`, r`social capital`, r`economic capital`, r`material culture`],
    correctAnswer: 0,
    explanation: r`Cultural capital is the non-financial assets, such as knowledge, tastes and manners, that confer advantage, and her ease in elite settings is exactly that. Social capital would be an advantage from networks and connections, which the scenario does not mention. Economic capital is ruled out by the equal incomes, and material culture refers to physical objects.`,
  },
  [r`What is cultural lag?`]: {
    question: r`Delivery drones become common in a region within two years. There are still no rules about flying over private yards, and neighbors disagree about whether filming from the air is acceptable. Sociologists call this gap:`,
    options: [r`cultural lag`, r`culture shock`, r`cultural diffusion`, r`cultural relativism`],
    correctAnswer: 0,
    explanation: r`Cultural lag is non-material culture, such as norms and laws, adapting more slowly than material culture, such as technology. Culture shock is an individual's disorientation in an unfamiliar culture. Cultural diffusion is the spread of an element between societies, and cultural relativism is judging a culture by its own standards.`,
  },
  [r`Socialization is the process by which people:`]: {
    question: r`Which change in a growing child is a result of socialization, not of biological maturation?`,
    options: [r`learning to wait her turn in a queue`, r`growing her first set of adult teeth`, r`gaining the balance needed to walk`, r`developing sharper distance vision`],
    correctAnswer: 0,
    explanation: r`Socialization is the process of learning the norms and values of one's society, and queueing is a social norm that has to be taught. Teeth, balance and vision develop through biological maturation whether or not anyone teaches a rule. Choosing one of those confuses growing up physically with learning how to behave among others.`,
  },
  [r`Display rules refer to:`]: {
    question: r`At a funeral in one community, loud open weeping is expected; in another, mourners stay quiet and composed. Heart-rate recordings suggest the mourners in both communities feel grief of similar intensity. The difference in behavior is best explained by:`,
    options: [r`display rules for emotional expression`, r`proxemic rules for personal distance`, r`innate differences in emotional depth`, r`universal rules for facial expression`],
    correctAnswer: 0,
    explanation: r`Display rules are cultural norms about when and how strongly an emotion may be shown, so the same grief looks different in the two communities. Proxemics concerns personal space, not emotional expression. The similar recordings rule out innate differences in feeling, and a universal rule could not explain a difference between cultures.`,
  },
  [r`Identity is influenced by all EXCEPT:`]: {
    question: r`A magazine quiz claims that people with type O blood are natural leaders and people with type A blood are careful planners. Which response is best supported by evidence?`,
    options: [r`identity is shaped by blood type more than by family, peers or culture`, r`identity is shaped by social factors, and blood type has no such effect`, r`identity is fixed at birth, so neither culture nor blood type matters`, r`identity is shaped by blood type, but only in collectivist cultures`],
    correctAnswer: 1,
    explanation: r`Identity is shaped by social influences such as family, peers and culture, and there is no evidence that blood type affects personality. The claim that blood type matters more than upbringing, or matters in some cultures only, repeats the popular belief without support. Saying identity is fixed at birth ignores socialization altogether.`,
  },
  [r`Dependency theory argues underdevelopment results from:`]: {
    question: r`A country has exported raw cocoa at low prices to wealthy nations for a century and imports their costly machinery and finished chocolate. It remains poor. A dependency theorist would explain its poverty by saying that:`,
    options: [r`its traditional values have blocked the move to modern industry`, r`it has not yet passed through the required stages of growth`, r`its people lack the cultural capital needed for global trade`, r`exploitation by wealthy nations keeps it in a subordinate role`],
    correctAnswer: 3,
    explanation: r`Dependency theory argues that underdevelopment results from exploitation by wealthy nations, which lock poorer countries into supplying cheap raw goods. Blaming traditional values or unfinished growth stages is the modernization view that dependency theory criticizes. Cultural capital describes individual advantage within a society, not relations between nations.`,
  },
  [r`Resocialization is most dramatic in:`]: {
    question: r`Which person is most likely going through the most intense resocialization?`,
    options: [r`a student in week one at a new secondary school`, r`a clerk in week one at a new insurance office`, r`a retiree in week one of a new gardening club`, r`a recruit in week one of military basic training`],
    correctAnswer: 3,
    explanation: r`Resocialization is most dramatic in total institutions such as the military and prisons, where the prior identity is deliberately stripped and rebuilt. A new school, office or club teaches new norms, but the person goes home each day and keeps the old identity. Those settings involve ordinary secondary socialization, not an institution that controls every part of life.`,
  },
  [r`Modernization theory proposes societies develop by:`]: {
    question: r`An aid agency advises an agrarian country to repeat the steps that wealthy industrial nations took: mechanize farms, build factories and adopt "modern" values. Which theory guides this advice, and what is the main criticism of it?`,
    options: [r`modernization theory; it is ethnocentric and ignores colonial history`, r`dependency theory; it is ethnocentric and ignores colonial history`, r`modernization theory; it blames wealthy nations for global poverty`, r`dependency theory; it blames traditional values for global poverty`],
    correctAnswer: 0,
    explanation: r`Modernization theory says societies develop by following a path from traditional to industrial, and critics call it ethnocentric because it treats the wealthy nations' route as the standard and overlooks colonialism. Dependency theory is the critique, not the source of this advice. Blaming wealthy nations is what dependency theory does, and blaming traditional values is what modernization theory does.`,
  },
  [r`Role exit involves:`]: {
    question: r`After an injury ends her 15-year career, a professional swimmer stops introducing herself as an athlete, grieves the loss, and slowly builds a new daily routine and sense of who she is. This process is called:`,
    options: [r`role exit`, r`role strain`, r`role conflict`, r`role taking`],
    correctAnswer: 0,
    explanation: r`Role exit is disengaging from a role that has been central to one's identity, which is what leaving a long athletic career involves. Role strain is tension among the demands of a single role, and role conflict is tension between two different roles held at once. Role taking is imagining another person's perspective.`,
  },
  [r`A {{c1::subculture}} has distinct norms within the mainstream (e.g., med students); a {{c2::counterculture}} opposes dominant values (e.g., 1960s hippies).`]: {
    question: r`Group 1 is a club of amateur astronomers with its own jargon and meetups, whose members otherwise share mainstream values. Group 2 is a movement that refuses to use money, rejects schooling and campaigns to overturn the society's core values. The two groups are, in order:`,
    options: [r`a subculture, then a counterculture`, r`a counterculture, then a subculture`, r`a subculture, then another subculture`, r`a counterculture, then another counterculture`],
    correctAnswer: 0,
    explanation: r`A subculture has distinct norms inside the mainstream without rejecting it, which fits the astronomers. A counterculture defines itself against the dominant values, which fits the second movement. Calling both the same type misses that only the second group opposes the wider society.`,
  },
  [r`{{c1::Folkways}} are everyday norms of custom and politeness; violations (facing backward in an elevator) draw only mild disapproval.`]: {
    question: r`A new employee eats lunch at a shared table with her fingers while everyone else uses cutlery. If the cutlery norm in this office is a folkway, the most likely response from her colleagues is:`,
    options: [r`a formal written warning from a manager`, r`moral outrage and calls to dismiss her`, r`a few odd looks and some light teasing`, r`visceral disgust and lasting avoidance`],
    correctAnswer: 2,
    explanation: r`Folkways are everyday norms of custom and politeness, and breaking one draws only mild disapproval, such as odd looks. A formal warning or moral outrage would fit a more, a norm with moral weight and strong sanctions. Visceral disgust and expulsion are the reaction to a taboo.`,
  },
  [r`{{c1::Mores}} are morally significant norms drawing strong sanctions; {{c2::taboos}} are so deep that violation evokes revulsion, e.g., incest or cannibalism.`]: {
    question: r`In a village, a man who lies under oath is condemned as immoral and fined. Another man, found to have eaten human remains, is met with horror and permanently cast out. The norms the two men violated are, in order:`,
    options: [r`a taboo, then a more`, r`a folkway, then a more`, r`a more, then a taboo`, r`a folkway, then a taboo`],
    correctAnswer: 2,
    explanation: r`Lying under oath breaks a morally significant norm and draws a strong sanction, which makes it a more. Cannibalism evokes revulsion and expulsion, the mark of a taboo. Calling perjury a folkway understates it, since a folkway violation makes someone odd, not immoral, and the reversed order swaps the two reactions.`,
  },
  [r`What is ethnocentrism's functional side, per some sociologists?`]: {
    question: r`Members of a fishing cooperative are convinced that their methods and traditions are the best on the coast. Which pair of outcomes would sociologists expect this belief to produce?`,
    options: [r`weaker in-group loyalty, but less prejudice toward outsiders`, r`stronger in-group loyalty, and less prejudice toward outsiders`, r`stronger in-group loyalty, but more prejudice toward outsiders`, r`weaker in-group loyalty, and more prejudice toward outsiders`],
    correctAnswer: 2,
    explanation: r`Ethnocentrism has a functional side, since in-group pride strengthens solidarity and loyalty, but it also fuels prejudice and misjudgment of other groups. The options with weaker loyalty miss the group-binding function. The option pairing stronger loyalty with less prejudice ignores the social cost that comes with it.`,
  },
  [r`The {{c1::Sapir-Whorf}} hypothesis (linguistic relativity): the language we speak shapes how we perceive and think about the world.`]: {
    question: r`Speakers of a language with separate basic words for light blue and dark blue sort blue color chips across that boundary slightly faster than speakers of a language with one word for blue. Both groups can see the difference when asked. This result supports:`,
    options: [r`the strong form: language fully determines perception`, r`the strong form: thought is impossible without words`, r`the weak form: language influences habitual perception`, r`neither form: language has no effect on perception`],
    correctAnswer: 2,
    explanation: r`The weak version of the Sapir-Whorf hypothesis says language nudges habitual perception, which matches a small speed difference. The strong version is rejected, and here it fails because both groups can still see the distinction. Saying language has no effect ignores the measured difference between the groups.`,
  },
  [r`{{c1::Sanctions}} enforce norms and can be positive or negative, formal (a fine, a diploma) or informal (a smile, gossip, ostracism).`]: {
    question: r`A student caught plagiarizing is suspended by the dean. In the weeks that follow, her lab partners stop inviting her to their study sessions. In order, these two responses are which kinds of sanction?`,
    options: [r`negative informal, then negative formal`, r`positive formal, then negative informal`, r`negative formal, then negative informal`, r`negative formal, then positive informal`],
    correctAnswer: 2,
    explanation: r`Both responses punish, so both are negative sanctions. The suspension comes from an institution with official authority, which makes it formal, while being left out by peers arises in everyday interaction, which makes it informal. The other options either swap formal and informal or mislabel a punishment as a positive sanction.`,
  },
  [r`What are Mead's three stages in developing the self?`]: {
    question: r`A 4-year-old spends the afternoon pretending to be a bus driver, then a shopkeeper, speaking as each character in turn. She cannot yet follow a team game in which every player has a position. In Mead's sequence she is in:`,
    options: [r`the game stage`, r`the play stage`, r`the imitation stage`, r`the preparatory stage`],
    correctAnswer: 1,
    explanation: r`In the play stage a child takes on one role at a time, as in pretending to be a bus driver and then a shopkeeper. The game stage requires managing several roles at once and grasping the generalized other, which she cannot yet do. The preparatory stage is imitation without meaning, and "imitation stage" is only another description of that earlier stage.`,
  },
  [r`{{c1::Material}} culture is a society's physical objects (tools, dress, buildings); {{c2::nonmaterial}} culture is its values, beliefs, norms, and language.`]: {
    question: r`A company introduces a video-call app. Within a year, its employees regard keeping the camera off during a meeting as rude. How should the app and the camera expectation be classified?`,
    options: [r`the app is nonmaterial culture; the expectation is material`, r`the app is material culture; the expectation is nonmaterial`, r`the app and the expectation are both material culture`, r`the app and the expectation are both nonmaterial culture`],
    correctAnswer: 1,
    explanation: r`Material culture is a society's physical objects and technology, so the app counts as material. The expectation about cameras is a norm, which belongs to nonmaterial culture. The scenario shows the two interacting: a new tool reshapes the rules of communication.`,
  },
  [r`{{c1::Cultural lag}} (Ogburn): material culture changes faster than nonmaterial culture, e.g., laws and ethics trailing genetic testing technology.`]: {
    question: r`In 2030 a country gains the ability to store any person's full genome in a phone app. Ogburn's idea of cultural lag predicts which sequence?`,
    options: [r`the technology spreads first; privacy norms and laws follow later`, r`privacy norms and laws form first; the technology spreads later`, r`the technology and the privacy norms change at one shared pace`, r`the technology spreads, and privacy norms never adapt to it at all`],
    correctAnswer: 0,
    explanation: r`Ogburn argued that material culture changes faster than nonmaterial culture, so the technology arrives before the norms and laws that govern it. Putting the norms first, or having both move together, reverses or removes the lag. The gap is temporary: it causes problems until the norms catch up, so "never adapt" goes too far.`,
  },
  [r`Why does cultural relativism matter in medicine, and where are its limits?`]: {
    question: r`A hospitalized patient's family asks that her meals follow their religious dietary rules and that a traditional healer be allowed to visit. On another ward, a parent cites tradition to refuse a treatment that a child needs to survive. Which response shows both the value and the limit of cultural relativism?`,
    options: [r`accommodate the diet and healer, and defer on the child as well`, r`refuse the diet and healer, but defer on the child's treatment`, r`refuse the diet and healer, and act to protect the child`, r`accommodate the diet and healer, but act to protect the child`],
    correctAnswer: 3,
    explanation: r`Understanding health beliefs in their own context improves care and trust, so harmless practices such as a diet and a healer's visit are accommodated. The limit comes when a practice causes harm, where duties such as child protection take priority. Deferring on the child ignores that limit, and refusing the harmless requests ignores the value.`,
  },
  [r`What is a cultural universal? Give examples.`]: {
    question: r`An anthropologist surveys 200 societies and finds that every one holds some rite for its dead, though the rites range from burial to cremation to exposure on a platform. Which conclusion is correct?`,
    options: [r`funeral rites are a cultural universal whose form varies`, r`funeral rites are a cultural universal whose form is fixed`, r`funeral rites are a folkway found only in some societies`, r`burial is a cultural universal because most groups use it`],
    correctAnswer: 0,
    explanation: r`A cultural universal is a practice found in every known society, and funeral rites qualify even though their forms differ enormously. Saying the form is fixed contradicts the survey. A practice present in all 200 societies is not limited to some, and burial is one form among several, so it is not itself universal.`,
  },
  [r`What is xenocentrism?`]: {
    question: r`A shopper insists that a locally made medicine must be worse than an identical imported one, and says her own country's schools, food and films are all second-rate compared with those abroad. Her outlook is an example of:`,
    options: [r`ethnocentrism`, r`xenocentrism`, r`culture shock`, r`cultural lag`],
    correctAnswer: 1,
    explanation: r`Xenocentrism is judging one's own culture as inferior to others, such as assuming imported goods are inherently better. Ethnocentrism is the reverse, judging other cultures by one's own as the standard. Culture shock is disorientation in an unfamiliar culture, and cultural lag is norms trailing technology.`,
  },
  [r`How does the workplace act as an agent of socialization?`]: {
    question: r`Which observation best shows a workplace acting as an agent of socialization?`,
    options: [r`a new hire adopts the team's jargon and dress within a month`, r`a new hire receives a higher salary after a strong first year`, r`a new hire moves to a nearer flat to shorten the commute`, r`a new hire recalls table manners taught by her grandparents`],
    correctAnswer: 0,
    explanation: r`The workplace socializes adults into occupational norms such as dress, hierarchy, jargon and professional ethics, so picking up the team's jargon and dress is the clearest sign. A pay rise and a shorter commute are practical changes, not the learning of norms. Table manners from grandparents were taught by the family, a different agent.`,
  },
  [r`What is a degradation ceremony?`]: {
    question: r`On arrival at a detention center, a man is photographed, made to hand over his own clothes, issued a uniform and addressed by a number in front of the other detainees. In Garfinkel's terms, the function of this procedure is to:`,
    options: [r`reward his conformity with a positive formal sanction`, r`rehearse a future role that he hopes to occupy later`, r`pass the group's culture down to the next generation`, r`strip his prior identity and assign a stigmatized one`],
    correctAnswer: 3,
    explanation: r`This intake is a degradation ceremony: a ritual that publicly strips a person's identity and assigns a stigmatized one, often the entry point of resocialization. It is not a reward, so a positive sanction does not fit. Rehearsing a hoped-for role is anticipatory socialization, and passing culture down generations is cultural transmission.`,
  },
  [r`Why is language considered the keystone of nonmaterial culture?`]: {
    question: r`The last fluent speakers of a community's language die, and its young people speak only another language. Anthropologists expect much of the community's oral history and ritual knowledge to be lost. The best reason is that:`,
    options: [r`language is a part of material culture that decays quickly`, r`language stores and transmits culture across generations`, r`language is inherited genetically within each community`, r`language fully determines what its speakers can think`],
    correctAnswer: 1,
    explanation: r`Language is the keystone of nonmaterial culture because it stores accumulated knowledge and passes it between generations, so losing it cuts the line of transmission. Language is nonmaterial, not a physical object, and it is learned, not inherited. The claim that language fully determines thought is the rejected strong form of linguistic relativity.`,
  },
  [r`In Mead's theory, what are the 'I' and the 'me'?`]: {
    question: r`At a funeral a man feels a sudden urge to tell a joke. He pictures how the mourners would judge him and stays silent. In Mead's terms, the urge and the restraint come from:`,
    options: [r`the "me", then the "I"`, r`the "I", then the "me"`, r`the "I" in both cases`, r`the "me" in both cases`],
    correctAnswer: 1,
    explanation: r`The "I" is the spontaneous, acting self, so the sudden urge belongs to it. The "me" is the socialized self that holds the internalized expectations of others, so the restraint based on imagined judgment belongs to it. The reversed option swaps the two, and the single-source options ignore that the self is a conversation between both.`,
  },
  [r`What are the three steps of Cooley's looking-glass self?`]: {
    question: r`A teenage violinist's audience enjoyed her recital, but she believes they were bored, and she feels ashamed. This fits Cooley's looking-glass self because her self-feeling arises from:`,
    options: [r`the judgment the audience actually made`, r`the judgment she imagines the audience made`, r`the standard she privately sets for herself`, r`the skill she objectively showed on stage`],
    correctAnswer: 1,
    explanation: r`In the looking-glass self we imagine how we appear, imagine the other's judgment, and feel pride or shame from that imagined judgment. Her shame follows what she thinks the audience felt, not what they actually felt, which rules out the actual judgment. A private standard or objective skill leaves out the imagined view of others that Cooley's steps depend on.`,
  },
  [r`How does acculturation differ from assimilation?`]: {
    question: r`After moving abroad, a woman learns the local language for work and adopts local dress. At home she still speaks her first language, cooks the dishes she grew up with and observes her religion. Her adaptation is best described as:`,
    options: [r`assimilation without acculturation`, r`amalgamation of the two cultures`, r`separation from the host culture`, r`acculturation without assimilation`],
    correctAnswer: 3,
    explanation: r`Acculturation is adopting elements of another culture while possibly keeping one's own, which is what she has done. Assimilation would mean fuller absorption with loss of her distinct practices, and she has kept them. Amalgamation would produce a new blended culture, and separation would mean not adopting the language or dress at all.`,
  },
  [r`{{c1::Culture shock}} is the disorientation felt when immersed in an unfamiliar culture whose taken-for-granted norms no longer apply.`]: {
    question: r`In her first week abroad an exchange student stands too close in queues, arrives "on time" to an empty room, and cannot tell whether to bow or shake hands. She feels lost and exhausted. Which term names this, and what is its usual course?`,
    options: [r`culture shock, which usually worsens over the years`, r`culture shock, which usually eases with adjustment`, r`cultural lag, which usually eases with adjustment`, r`ethnocentrism, which usually eases with adjustment`],
    correctAnswer: 1,
    explanation: r`Culture shock is the disorientation felt when taken-for-granted norms about space, time and greetings stop working, and it typically eases through adjustment. It is a short-term reaction, so steady worsening over years does not describe it. Cultural lag is about norms trailing technology, and ethnocentrism would require her to judge the hosts by her own standards.`,
  },
  [r`{{c1::Assimilation}} is a minority absorbing the dominant culture, losing distinctiveness; {{c2::amalgamation}} melts groups into a genuinely new culture.`]: {
    question: r`Two port cities were each settled by an Arel majority and a Benu minority. A century later, everyone in the first city speaks Arel and follows Arel customs. Everyone in the second speaks a new creole and practices a blended religion unlike either original. What happened in each city?`,
    options: [r`amalgamation in the first, assimilation in the second`, r`assimilation in the first, amalgamation in the second`, r`multiculturalism in the first, amalgamation in the second`, r`assimilation in the first, multiculturalism in the second`],
    correctAnswer: 1,
    explanation: r`In the first city the minority was absorbed into the dominant culture and lost its distinctiveness, which is assimilation. In the second the groups melted into a genuinely new culture, which is amalgamation. Multiculturalism would leave both original cultures distinct and side by side, and that happened in neither city.`,
  },
  [r`{{c1::Resocialization}} is discarding old behaviors and identities to adopt new ones, most intensely inside total institutions like boot camp or prison.`]: {
    question: r`After twenty years as a salesman, a man enters a strict monastery. He gives up his possessions and former name, his old habits are corrected, and new ones are rewarded until his values have changed. This process is called:`,
    options: [r`primary socialization`, r`cultural transmission`, r`resocialization`, r`anticipatory socialization`],
    correctAnswer: 2,
    explanation: r`Resocialization is discarding old behaviors and identities to adopt new ones, usually by breaking down the old identity and rebuilding it with rewards and punishments. Primary socialization is early childhood learning in the family. Cultural transmission is passing culture down generations, and anticipatory socialization is rehearsing a role before holding it, while he is already living the new role.`,
  },
  [r`A {{c1::total institution}} (Goffman) controls every aspect of residents' lives — prisons, asylums, boot camps — cut off from wider society.`]: {
    question: r`Which feature would a sociologist need to see before calling a residential facility a total institution in Goffman's sense?`,
    options: [r`one authority schedules all sleep, meals and work on site`, r`residents share a hobby and gather on site each weekend`, r`staff hold more formal schooling than the residents do`, r`residents pay a fee and may leave whenever they choose`],
    correctAnswer: 0,
    explanation: r`A total institution controls every aspect of residents' lives under a single authority and cuts them off from wider society. A weekend hobby group and a gap in schooling leave most of life outside the facility's control. Residents who can leave at will are not cut off, which fails the definition.`,
  },
  [r`{{c1::Anticipatory}} socialization is rehearsing the norms of a future role, e.g., a premed shadowing physicians or an engaged couple cohabiting.`]: {
    question: r`A woman admitted to a police academy that starts next year begins reading officers' forums, picks up their terminology and trains on a fitness plan modeled on theirs. This behavior is best described as:`,
    options: [r`primary socialization`, r`reverse socialization`, r`resocialization`, r`anticipatory socialization`],
    correctAnswer: 3,
    explanation: r`Anticipatory socialization is rehearsing the norms of a future role by adopting a reference group's values in advance, which is what she does before holding the job. Primary socialization is childhood learning in the family. Reverse socialization is the young teaching the old, and resocialization strips an existing identity, usually inside an institution she has not yet entered.`,
  },
  [r`{{c1::Cultural diffusion}} spreads elements between societies (yoga to the West); {{c2::cultural transmission}} passes culture down generations within one.`]: {
    question: r`A noodle dish arrives in a coastal town with foreign traders and catches on. A century later, grandparents in the town teach the recipe to their grandchildren as a local tradition. The two stages show, in order:`,
    options: [r`cultural transmission, then cultural diffusion`, r`cultural diffusion at both of the two stages`, r`cultural diffusion, then cultural transmission`, r`cultural transmission at both of the two stages`],
    correctAnswer: 2,
    explanation: r`Cultural diffusion spreads an element between societies, as when traders bring a dish from elsewhere. Cultural transmission passes culture down the generations within one society, as when grandparents teach grandchildren. The reversed option swaps the two terms, and the single-term options miss that one stage crosses a cultural boundary and the other does not.`,
  },
  [r`What do cases of extreme isolation (e.g., Genie) demonstrate about socialization?`]: {
    question: r`A child is rescued at age 13 after years with almost no human contact and then receives intensive language teaching. Which outcome is most consistent with documented cases of this kind?`,
    options: [r`full recovery of speech within a year of teaching`, r`partial gains in speech, with deficits that persist`, r`no change at all, because language is fixed at birth`, r`normal grammar at once, because speech simply matures`],
    correctAnswer: 1,
    explanation: r`Cases of extreme isolation show profound deficits in speech and attachment that are only partly recoverable, which points to sensitive periods for socialization. Full recovery ignores that limit. Language being fixed at birth, or emerging on its own by maturation, both deny that language and the self require social interaction.`,
  },
  [r`Distinguish high culture from popular culture.`]: {
    question: r`A hiring partner bonds with a job candidate over opera and classical painting and rates the candidate as "refined" and a good fit. In Bourdieu's analysis, the candidate's tastes are:`,
    options: [r`popular culture that works as cultural capital`, r`high culture that works as a counterculture`, r`high culture that works as cultural capital`, r`popular culture that works as material culture`],
    correctAnswer: 2,
    explanation: r`Opera and fine art are high culture, associated with elites, and Bourdieu argued that a taste for them functions as cultural capital that confers advantage. Popular culture is mass-consumed entertainment such as television and sports, which is not what the candidate displayed. A counterculture opposes dominant values, the opposite of fitting in with an elite employer.`,
  },
  [r`What are the phases of a rite of passage?`]: {
    question: r`A nursing student has finished her last class, but the pinning ceremony that grants the title of nurse is a week away. She says she feels "no longer a student, but not yet a nurse." In van Gennep's scheme of a rite of passage, her current phase is:`,
    options: [r`separation`, r`reincorporation`, r`liminality`, r`anticipation`],
    correctAnswer: 2,
    explanation: r`A rite of passage runs from separation, through transition, to reincorporation, and the in-between transition phase is called liminality. She has already separated from the student status, so separation is behind her. Reincorporation comes only when she rejoins the community with the new status at the ceremony, and anticipation is not one of the phases.`,
  },
  [r`How can ethnic enclaves affect assimilation?`]: {
    question: r`A newly arrived baker settles in a neighborhood where the shops, banks and places of worship all operate in her first language. Compared with a similar immigrant who settles where no such community exists, she would be expected to have:`,
    options: [r`harder early settlement but faster language learning`, r`easier early settlement and faster language learning`, r`harder early settlement and slower language learning`, r`easier early settlement but slower language learning`],
    correctAnswer: 3,
    explanation: r`Ethnic enclaves supply social capital, jobs and familiar institutions, which eases arrival. Because daily life can be carried on in the first language, they can slow linguistic and structural assimilation. The other options get one or both effects backward.`,
  },
  [r`{{c1::Multiculturalism}} (pluralism) endorses distinct cultures coexisting with equal standing — the 'salad bowl' rather than the melting pot.`]: {
    question: r`A government describes its policy toward its cultural communities as "a salad bowl, not a melting pot." Which program fits that policy?`,
    options: [r`funding schools that teach in each community's language`, r`requiring every school to teach in one national language`, r`rewarding families who give up their heritage customs`, r`blending all traditions into one new national festival`],
    correctAnswer: 0,
    explanation: r`The salad bowl is multiculturalism, or pluralism: distinct cultures coexist with equal standing and keep their languages and traditions. Requiring one language and rewarding families for dropping customs are assimilationist. Blending all traditions into a new one is amalgamation, the melting pot the policy rejects.`,
  },
  [r`What makes something a symbol in the cultural sense?`]: {
    question: r`In one country a raised thumb signals approval; in another the same gesture is a serious insult. This contrast shows that the meaning of a cultural symbol is:`,
    options: [r`innate and shared by all human groups`, r`arbitrary and learned within a culture`, r`fixed by the gesture's physical form`, r`part of a society's material culture`],
    correctAnswer: 1,
    explanation: r`A symbol carries a shared meaning recognized by members of a culture, and that meaning is arbitrary and learned, so it can differ or offend elsewhere. If the meaning were innate or set by the physical form, the same gesture would mean the same thing everywhere. A gesture's meaning is an idea, so it belongs to nonmaterial culture.`,
  },
  [r`How do laws relate to norms?`]: {
    question: r`A town still has an ordinance banning whistling on Sundays, which nobody supports or enforces. In the same town, lying to a close friend is strongly condemned but is not illegal. Together these facts show that:`,
    options: [r`every law reflects a current more, and all mores become law`, r`some laws outlast their norms, and not all mores become law`, r`laws are folkways, and mores are never backed by sanctions`, r`laws are informal norms, and mores are always written down`],
    correctAnswer: 1,
    explanation: r`Laws are norms formally codified and enforced by the state, usually derived from mores. The dead ordinance shows a law can outlast the norm that produced it, and the unlegislated rule about lying shows not every more becomes law. Laws are formal, not informal or mere folkways, and mores are backed by strong sanctions.`,
  },
  [r`Which socialization agent dominates in adolescence, and what does it uniquely teach?`]: {
    question: r`A 15-year-old now takes her cues on music, slang and clothing from friends, and works out the rules of the group with them when no adult is present. Which agent of socialization is at work, and what does it uniquely teach?`,
    options: [r`the family, which teaches negotiation among equals`, r`peer groups, which teach deference to authority`, r`peer groups, which teach negotiation among equals`, r`the school, which teaches deference to authority`],
    correctAnswer: 2,
    explanation: r`Peer groups dominate in adolescence and uniquely offer interaction among equals: negotiation and identity experimentation outside adult supervision. The family and the school are run by adults, so relations in them are not among equals. Deference to authority is what adult-led settings teach, not what a peer group teaches.`,
  },
  [r`Classify: a hospital forbids staff from accepting gifts; a nurse who does is fired. Folkway, more, or taboo?`]: {
    question: r`A university bars professors from grading their own relatives. One who does so loses his post, and colleagues call it a breach of fairness, though nobody reacts with disgust. This norm is best classified as:`,
    options: [r`a folkway that has been formalized into policy`, r`a more that has been formalized into policy`, r`a taboo that has been formalized into policy`, r`a folkway that is enforced by mild disapproval`],
    correctAnswer: 1,
    explanation: r`The rule carries moral weight about fairness and trust, and breaking it brings a serious sanction, so it is a more written into policy. A folkway violation would draw only mild disapproval, not dismissal. A taboo would evoke visceral revulsion, which the colleagues do not feel.`,
  },
  [r`{{c1::Sex}} refers to biological characteristics and {{c2::gender}} to socially constructed roles; gender identity is internal, orientation is attraction.`]: {
    question: r`A clinic note on one patient contains two entries. Entry 1: "XY chromosomes, testes present." Entry 2: "Is expected by his family to be the breadwinner and to hide sadness." What does each entry describe?`,
    options: [r`gender in entry 1, sex in entry 2`, r`sex in entry 1, orientation in entry 2`, r`sex in entry 1, gender in entry 2`, r`gender identity in entry 1, sex in entry 2`],
    correctAnswer: 2,
    explanation: r`Sex refers to biological characteristics such as chromosomes and gonads, so entry 1 describes sex. Gender refers to socially constructed roles and expectations, so entry 2 describes gender. Orientation is about attraction and gender identity is an internal sense of self, and neither entry records those.`,
  },
  [r`Hall's {{c1::proxemics}} studies culturally patterned use of personal space; a physical exam routinely enters the {{c2::intimate}} zone.`]: {
    question: r`During history-taking, a patient keeps stepping back each time the clinician leans in, and the clinician reads this as evasive. Later the clinician listens to the patient's chest with a stethoscope. Which concept explains the stepping back, and which of Hall's zones does the chest exam enter?`,
    options: [r`proxemics; the public zone`, r`display rules; the intimate zone`, r`display rules; the social zone`, r`proxemics; the intimate zone`],
    correctAnswer: 3,
    explanation: r`Proxemics is the study of culturally patterned use of personal space, so a patient who prefers a larger conversational distance is following a different spatial norm, not being evasive. A physical exam routinely enters the intimate zone, the closest of Hall's distances. Display rules govern emotional expression, not distance, and the public zone is the farthest one.`,
  },
  [r`A patient describes an ataque de nervios after a family loss. What is a cultural concept of distress, and how should it be handled clinically?`]: {
    question: r`A patient says she has a named illness that is well known in her home community: chest heat, fatigue and worry after a long family conflict. It matches no single DSM diagnosis. What is the best clinical approach?`,
    options: [r`dismiss it as folklore and treat only lab-confirmed disease`, r`record it as malingering because no DSM category fits it`, r`assume every patient from her community has the condition`, r`treat it as real distress and explore what it means to her`],
    correctAnswer: 3,
    explanation: r`Her illness is a cultural concept of distress: a symptom cluster recognized within a culture, with shared meaning and an expected course. Such presentations are treated as genuine distress and explored, for example with a cultural formulation interview. Dismissing it or calling it malingering denies real suffering, and assuming it of everyone from her community is stereotyping.`,
  },
  [r`Some second-generation immigrants advance economically while others assimilate into disadvantaged contexts. Name this model and what predicts each path.`]: {
    question: r`Two families emigrate from the same country in the same year. One settles near well-funded schools and a thriving coethnic business community, and its children become professionals. The other settles where schools are underfunded and discrimination is common, and its children's prospects fall. Which model fits, and what explains the split?`,
    options: [r`straight-line assimilation; the receiving context differs`, r`segmented assimilation; the country of origin differs`, r`straight-line assimilation; the time since arrival differs`, r`segmented assimilation; the receiving context differs`],
    correctAnswer: 3,
    explanation: r`Segmented assimilation holds that second-generation outcomes depend on the receiving context: neighborhood, school quality, discrimination and coethnic resources. Straight-line assimilation predicts one upward path for everyone, which the split contradicts. The families share a country of origin and a year of arrival, so neither of those can explain the difference.`,
  },
  [r`Kleinman's {{c1::explanatory model}} interview asks what the patient thinks caused the illness, its name, its course, and the treatment expected.`]: {
    question: r`A man with high blood pressure takes his pills only on tense days, because he believes "hypertension" means being too tense. Which question from Kleinman's explanatory model interview would most directly have uncovered this?`,
    options: [r`"Can you list each medicine you take now?"`, r`"Has anyone in your family had a stroke?"`, r`"How many days a week do you exercise?"`, r`"What do you think has caused your problem?"`],
    correctAnswer: 3,
    explanation: r`The explanatory model interview asks what the patient thinks caused the illness, what it is called, its course and the treatment expected, which exposes the gap between his belief and the clinician's framework. A medication list, a family history and an exercise count are standard clinical questions. They gather facts but never ask for the patient's own account of the illness.`,
  },
  [r`Distinguish high-context and low-context communication cultures, and give one clinical implication.`]: {
    question: r`A clinician asks, "Will you take this medicine every day, yes or no?" The patient, raised in a high-context communication culture, pauses, looks down and quietly says yes. What is the best reading and next step?`,
    options: [r`the spoken yes is literal, so no follow-up is required`, r`the hesitation shows a low-context style, so be blunter`, r`the spoken yes is a display rule, so repeat the question`, r`the hesitation may signal refusal, so ask open questions`],
    correctAnswer: 3,
    explanation: r`High-context communication relies on indirectness and nonverbal cues, so hesitation can signal refusal even when the word is yes, and a direct yes-or-no question can produce false agreement. Taking the yes literally applies a low-context reading to a high-context speaker. Being blunter or repeating the same closed question would only repeat the problem.`,
  },
  [r`{{c1::Primary}} socialization is early childhood learning of basic norms in the family; {{c2::secondary}} socialization occurs later in schools and workplaces.`]: {
    question: r`Grandparents raising a 3-year-old teach him to say please, to eat with a spoon and not to hit his sister. Which type of socialization is this?`,
    options: [r`primary socialization`, r`secondary socialization`, r`anticipatory socialization`, r`reverse socialization`],
    correctAnswer: 0,
    explanation: r`Primary socialization is the early childhood learning of basic norms within the family, which is what the grandparents provide. Secondary socialization comes later in schools and workplaces. Anticipatory socialization rehearses a future role, and reverse socialization runs upward, with the young teaching the old.`,
  },
  [r`{{c1::Prescriptive}} norms state what one should do; {{c2::proscriptive}} norms state what one must not do, and are usually enforced more forcefully.`]: {
    question: r`A teaching laboratory posts two rules: "Wear goggles at the bench" and "Never pipette by mouth." In order, these two norms are:`,
    options: [r`proscriptive, then prescriptive`, r`prescriptive in both cases`, r`prescriptive, then proscriptive`, r`proscriptive in both cases`],
    correctAnswer: 2,
    explanation: r`A prescriptive norm states what one should do, such as wearing goggles. A proscriptive norm states what one must not do, such as pipetting by mouth. The reversed option swaps the two prefixes, and the single-type options miss that one rule commands an action while the other forbids one.`,
  },
  [r`Heavy television viewers overestimate crime rates and distrust strangers more than light viewers. Name the theory and its key confound.`]: {
    question: r`In a survey, people who watch many hours of hospital dramas each day estimate that most resuscitation attempts succeed, far above the real rate, while light viewers give lower estimates. Which reading fits cultivation theory and states the right caution?`,
    options: [r`heavy viewing must shape beliefs, since a survey proves causation`, r`viewers copy a single modeled act, but the data are correlational`, r`viewers choose shows by belief, since a survey proves causation`, r`heavy viewing may shape beliefs, but the data are correlational`],
    correctAnswer: 3,
    explanation: r`Gerbner's cultivation theory says sustained exposure to media portrayals shapes beliefs about social reality. The caution is that survey data are correlational, so people who already hold a belief may also watch more. A survey cannot prove causation in either direction, and copying one modeled act describes observational learning, not cultivation.`,
  },
  [r`Neugarten's {{c1::social clock}} is a culture's expected timetable for life events, so being {{c2::off-time}} itself produces distress.`]: {
    question: r`One man is widowed at 34 and another at 82. Based on Neugarten's social clock, which prediction is best supported?`,
    options: [r`the 82-year-old tends to suffer more, as the loss is off-time`, r`both suffer equally, as the life event itself is the same`, r`the 34-year-old tends to suffer more, as the loss is off-time`, r`both suffer equally, as age norms are set by biology alone`],
    correctAnswer: 2,
    explanation: r`The social clock is a culture's expected timetable for life events, and events that arrive off-time are more distressing than on-time ones. Widowhood at 34 is far earlier than expected, while at 82 it is on-time, so calling the later loss off-time misapplies the term. Age norms are cultural and shift by cohort, so equal distress is not the prediction.`,
  },
  [r`Immigrants may speak the new language fluently yet remain excluded from clubs, friendship circles, and intermarriage. Distinguish the two assimilations.`]: {
    question: r`A second-generation engineer speaks the majority language natively and dresses and celebrates as his colleagues do. He is never invited into their homes, and local families discourage marriage into his community. Which assimilation has he achieved?`,
    options: [r`cultural but not structural assimilation`, r`structural but not cultural assimilation`, r`both cultural and structural assimilation`, r`neither cultural nor structural assimilation`],
    correctAnswer: 0,
    explanation: r`Cultural assimilation is adopting the host culture's language, dress and customs, which he has done. Structural assimilation is entry into friendship networks, primary institutions and families, which he has been denied. Gordon argued that this second step is far harder and is where discrimination operates.`,
  },
  [r`A physician's technical vocabulary leaves a patient nodding without understanding. Analyze this using culture and socialization concepts.`]: {
    question: r`Three months into her first job, a nurse tells a patient's son, "He's NPO until the consult, then PRN analgesia." The son nods but understands nothing. Which analysis is correct?`,
    options: [r`her argot shows membership of a counterculture; teach-back can close the gap`, r`her argot shows primary socialization; saying it again louder closes the gap`, r`her argot shows socialization into a subculture; teach-back can close the gap`, r`her argot shows cultural lag; a handout in the same terms closes the gap`],
    correctAnswer: 2,
    explanation: r`Medicine works as a subculture with its own argot, and fluency in it marks completed professional socialization. The mismatch leaves the listener with low health literacy in that moment, and teach-back is the standard corrective. A counterculture opposes dominant values, primary socialization is childhood learning, and cultural lag is norms trailing technology.`,
  },
  [r`One resident washes hands even when unobserved; another only when the attending is watching. Distinguish internalization from mere compliance.`]: {
    question: r`A city switches off all its speed cameras. Driver A's speed on camera-free roads does not change, while Driver B's speed rises at once. What does this show about the speed-limit norm?`,
    options: [r`B had internalized the norm; A had only been complying`, r`A and B had both internalized the norm in the same way`, r`A had internalized the norm; B had only been complying`, r`A and B had both only been complying with the norm`],
    correctAnswer: 2,
    explanation: r`Internalization means the norm has become part of the self, so behavior persists without surveillance, as with Driver A. Compliance is behavior that depends on sanctions and observation, so it stops when the cameras go, as with Driver B. The reversed option swaps the two, and the options treating both drivers alike ignore that only one changed.`,
  },
  [r`In {{c1::collectivist}} cultures medical decisions are often family-centered; {{c2::individualist}} cultures center the individual patient's autonomy.`]: {
    question: r`A physician tells an elderly patient's adult children that the diagnosis must be given directly to the patient, who alone will decide on treatment. The children had expected to be told first and to decide together as a family. Which cultural orientations are in conflict?`,
    options: [r`the family holds individualist norms; the physician, collectivist ones`, r`the family and the physician both hold collectivist norms, applied differently`, r`the family and the physician both hold individualist norms, applied differently`, r`the family holds collectivist norms; the physician, individualist ones`],
    correctAnswer: 3,
    explanation: r`In collectivist cultures medical decisions are often family-centered, which matches the children's expectation. Individualist cultures center the individual patient's autonomy, which matches the physician's stance. The reversed option swaps the two, and the same-orientation options cannot explain why the two sides disagree about who should be told and who decides.`,
  },
  [r`Medical students learn detachment, hierarchy, and what not to say by watching residents rather than from the syllabus. Name both concepts at work.`]: {
    question: r`A law firm's orientation never mentions it, yet within months every first-year associate has learned not to contradict a partner in front of clients and to hide fatigue, by watching senior associates who are praised for doing so. Which concepts are at work?`,
    options: [r`anticipatory socialization through a formal curriculum`, r`professional socialization through a hidden curriculum`, r`primary socialization through a hidden curriculum`, r`resocialization through a degradation ceremony`],
    correctAnswer: 1,
    explanation: r`Learning a profession's culture is professional socialization, and here it happens through the hidden curriculum: informal norms, role modeling and the reward structure, not the official syllabus. The associates already hold the role, so it is not anticipatory, and nothing was formally taught. Primary socialization is childhood learning, and no identity-stripping ritual took place.`,
  },
  [r`How does religion function as an agent of socialization, and what is one documented health correlate?`]: {
    question: r`A 20-year study finds that adults who attend religious services weekly have lower mortality than non-attenders. Which interpretation is most defensible?`,
    options: [r`social support may help, and so the study has proved causation`, r`social support may help, but healthier people also attend more`, r`attendance is random, so no confounding variable is possible`, r`ritual has no social role, so the link is pure coincidence`],
    correctAnswer: 1,
    explanation: r`Religion supplies a reference group and a dense social network, so social support, lower substance use and coping resources are plausible pathways. The estimate is confounded because healthier people are more able to attend. An observational study cannot prove causation, attendance is not random, and religion plainly has a social role.`,
  },
  [r`{{c1::Acculturative stress}} is the ongoing strain of adapting to a new culture, distinct from the brief disorientation of {{c2::culture shock}}.`]: {
    question: r`Which person is experiencing acculturative stress, as distinct from culture shock?`,
    options: [r`a tourist on day two dazed by unfamiliar greetings and food`, r`a resident of six years who rates all imports as superior`, r`a tourist on day two who judges local food by home standards`, r`a resident of six years worn down by juggling two sets of norms`],
    correctAnswer: 3,
    explanation: r`Acculturative stress is the ongoing strain of adapting to a new culture, so it fits a long-term resident worn down by balancing two sets of norms. The dazed tourist shows culture shock, the brief early disorientation. Rating all imports as superior is xenocentrism, and judging local food by home standards is ethnocentrism.`,
  },
  [r`Parents describe newborn daughters as delicate and sons as strong despite matched birth records. Name the process and its sociological reading.`]: {
    question: r`Adults are handed the same infant on two occasions. Dressed in blue, the infant is described as sturdy and offered a toy hammer; dressed in pink, it is described as sweet and offered a doll. What is the best sociological reading?`,
    options: [r`gender socialization, since treatment follows the label and not the child`, r`biological sex differences, since the infant behaved differently each time`, r`anticipatory socialization, since the infant rehearsed a future adult role`, r`cultural lag, since the adults' norms trailed behind a new technology`],
    correctAnswer: 0,
    explanation: r`Gender socialization means agents transmit gender expectations from birth, so differences partly reflect differential treatment and not innate traits. The infant was the same child both times, so biological differences cannot explain the change. An infant is not rehearsing a future role, and no technology is involved, which rules out anticipatory socialization and cultural lag.`,
  },
}
